mapper.select:
SELECT identity_key_id AS identityKeyId, party_id AS partyId, identifier_type AS identifierType,
  issuing_country AS issuingCountry, issuer_scope_key AS issuerScopeKey,
  identifier_key_value AS identifierKeyValue, create_time AS createTime, update_time AS updateTime
FROM t_party_identity_key
WHERE identifier_type=#{identifierType} AND issuer_scope_key=#{issuerScopeKey}
  AND identifier_key_value=#{keyValue}
